$questions = @(
    @{id="rta_001"; text="Tell me about a time you had to fill a hard-to-fill technical role. How did you approach the sourcing strategy?"; category="behavioral"; seniority=@("entry","mid","senior"); answer_framework=@{structure="STAR"; key_points=@("Identified the specific technical skills gap and mapped it to candidate profiles","Used Boolean search and LinkedIn Recruiter to find passive candidates","Collaborated with hiring managers to refine job requirements","Tracked sourcing channels to measure time-to-fill for the role","Built a talent pipeline for future similar positions"); strong_answer_signals=@("Quantified sourcing results with metrics","Showed proactive pipeline building","Demonstrated knowledge of Boolean search operators"); avoid=@("Vague descriptions of the role","Blaming hiring managers for delays","Focusing only on one sourcing channel")}},
    @{id="rta_002"; text="Describe a situation where you had to coordinate interviews for a high-priority hire across multiple time zones. How did you ensure a smooth process?"; category="situational"; seniority=@("mid","senior","manager"); answer_framework=@{structure="STAR"; key_points=@("Mapped all stakeholders availability using a scheduling tool","Created a shared calendar and communication plan","Prepared interview kits and logistics for each panelist","Managed candidate expectations with clear timelines","Coordinated backup plans for schedule conflicts"); strong_answer_signals=@("Used ATS or scheduling tools efficiently","Showed exceptional organizational skills","Demonstrated cross-cultural communication awareness"); avoid=@("Ignoring time zone differences","Forgetting to brief interviewers","Overcomplicating the scheduling process")}},
    @{id="rta_003"; text="Why do you want to move into recruiting, and what motivates you to excel in this field?"; category="motivation"; seniority=@("entry","mid","senior"); answer_framework=@{structure="Framework"; key_points=@("Connect your interest in people and business outcomes","Explain how recruiting aligns with your values","Highlight a specific moment that sparked your interest","Discuss what excites you about talent strategy","Mention your long-term career vision in TA"); strong_answer_signals=@("Authentic personal connection to the work","Understanding of recruiting as a strategic function","Enthusiasm for continuous learning"); avoid=@("Generic answers about helping people","Saying you just like talking to people","Dismissing the business impact of recruiting")}},
    @{id="rta_004"; text="A candidate you source turns out to be significantly underqualified for the role after the first interview. How do you handle this?"; category="situational"; seniority=@("entry","mid"); answer_framework=@{structure="STAR"; key_points=@("Reviewed the candidate profile against job requirements honestly","Provided constructive feedback to the candidate gracefully","Reassessed the sourcing criteria with the hiring manager","Adjusted search parameters to find better matches","Maintained the candidate relationship for future roles"); strong_answer_signals=@("Showing empathy while being honest","Taking responsibility for the mismatch","Demonstrating a learning mindset"); avoid=@("Blaming the hiring manager","Dismissing the candidate rudely","Ignoring the feedback loop")}},
    @{id="rta_005"; text="Walk me through your process for writing a job description that attracts top talent. What elements do you prioritize?"; category="technical"; seniority=@("entry","mid","senior"); answer_framework=@{structure="Framework"; key_points=@("Start with a clear summary of the role and its impact","Highlight essential qualifications without gating unnecessarily","Include company culture and growth opportunities","Use inclusive language to broaden the candidate pool","Optimize for ATS parsing and searchability"); strong_answer_signals=@("Knowledge of inclusive language best practices","Understanding of ATS optimization","Focus on candidate experience"); avoid=@("Copying generic templates","Using jargon or elitist language","Omitting salary ranges when possible")}},
    @{id="rta_006"; text="Tell me about a time you used Boolean search to find a passive candidate. What search string did you build and what was the result?"; category="technical"; seniority=@("mid","senior"); answer_framework=@{structure="STAR"; key_points=@("Defined the target candidate profile and required skills","Constructed a Boolean string using AND, OR, and NOT operators","Used LinkedIn Recruiter and other platforms to execute the search","Refined the search based on initial results quality","Achieved measurable results in terms of candidates sourced"); strong_answer_signals=@("Demonstrated mastery of Boolean operators","Showed ability to iterate on search strategies","Quantified sourcing outcomes"); avoid=@("Making up search strings without explanation","Not showing how results were validated","Ignoring platform-specific search features")}},
    @{id="rta_007"; text="Describe your experience with ATS systems. Which platforms have you used and how did you leverage them effectively?"; category="technical"; seniority=@("entry","mid","senior"); answer_framework=@{structure="Framework"; key_points=@("List the ATS platforms you have hands-on experience with such as Greenhouse, Lever, or Workday","Describe how you used the ATS for pipeline management","Explain how you configured workflows or automation","Show how you generated reports or metrics from the ATS","Discuss integration with other HR tools"); strong_answer_signals=@("Specific platform knowledge with real examples","Understanding of ATS reporting capabilities","Experience with workflow automation"); avoid=@("Naming platforms without explaining usage","Confusing ATS with CRM tools","Claiming expertise without concrete examples")}},
    @{id="rta_008"; text="How do you measure the effectiveness of your recruiting efforts? What metrics do you track and why?"; category="technical"; seniority=@("mid","senior","manager"); answer_framework=@{structure="Framework"; key_points=@("Track time-to-fill to measure sourcing efficiency","Monitor quality-of-hire through manager satisfaction and retention rates","Measure cost-per-hire to optimize budget allocation","Analyze source-of-hire to focus on the best channels","Report diversity metrics to ensure inclusive hiring goals"); strong_answer_signals=@("Linking metrics to business outcomes","Showing continuous improvement mindset","Understanding the difference between vanity and actionable metrics"); avoid=@("Focusing only on one metric","Not connecting metrics to strategy","Ignoring quality-of-hire in favor of speed")}},
    @{id="rta_009"; text="A hiring manager keeps rejecting every candidate you present. How do you handle this situation?"; category="behavioral"; seniority=@("mid","senior"); answer_framework=@{structure="STAR"; key_points=@("Scheduled a meeting to understand the hiring managers expectations","Reviewed the job description to identify any misalignment","Presented data on candidate quality and sourcing channels","Collaborated on adjusting criteria or expanding the search","Established a feedback loop to improve future submissions"); strong_answer_signals=@("Taking a collaborative rather than defensive approach","Using data to guide conversations","Demonstrating stakeholder management skills"); avoid=@("Becoming defensive or frustrated","Blaming the hiring manager","Continuing to submit candidates without feedback")}},
    @{id="rta_010"; text="Explain the difference between agency recruiting and in-house recruiting. What are the advantages and challenges of each?"; category="technical"; seniority=@("entry","mid","manager"); answer_framework=@{structure="Framework"; key_points=@("Define agency recruiting and its typical use cases such as high-volume or niche roles","Define in-house recruiting and its strategic advantages","Compare cost structures and speed of each approach","Discuss the level of employer brand control in each model","Explain when organizations choose one over the other"); strong_answer_signals=@("Clear understanding of both models","Knowledge of when each model is most effective","Awareness of cost and quality tradeoffs"); avoid=@("Saying one is always better than the other","Confusing staffing agencies with recruiting process outsourcing","Not understanding the business context for each")}},
    @{id="rta_011"; text="Tell me about a time you had to coordinate onboarding for a new hire. What did you do to ensure a positive first impression?"; category="situational"; seniority=@("entry","mid","senior"); answer_framework=@{structure="STAR"; key_points=@("Created a structured onboarding plan before the start date","Coordinated with IT, HR, and the hiring manager for setup","Prepared welcome materials and a first-week agenda","Scheduled introductory meetings with key team members","Gathered feedback from the new hire to improve future onboarding"); strong_answer_signals=@("Attention to detail in logistics","Proactive communication before day one","Focus on candidate experience and retention"); avoid=@("Leaving everything to the first day","Not coordinating with relevant departments","Ignoring the new hires feedback")}},
    @{id="rta_012"; text="How do you approach diversity and inclusion in your sourcing strategies? What specific actions do you take?"; category="motivation"; seniority=@("mid","senior","manager"); answer_framework=@{structure="Framework"; key_points=@("Audit sourcing channels for diversity gaps and representation","Use inclusive job descriptions and remove unnecessary barriers","Partner with diversity-focused organizations and universities","Implement blind resume screening where possible","Set and track diversity hiring goals with transparency"); strong_answer_signals=@("Concrete actions beyond just good intentions","Data-driven approach to diversity metrics","Understanding of systemic barriers in hiring"); avoid=@("Treating diversity as a checkbox exercise","Making assumptions about candidate groups","Not holding yourself accountable to measurable goals")}},
    @{id="rta_013"; text="Describe a time when you had to negotiate an offer with a candidate. How did you handle objections and reach a successful outcome?"; category="situational"; seniority=@("senior","manager"); answer_framework=@{structure="STAR"; key_points=@("Prepared a comprehensive compensation package aligned with market data","Listened to the candidates concerns and priorities before negotiating","Flexibly adjusted elements beyond just salary such as equity or remote work","Communicated the full value proposition of the offer","Closed the offer within a reasonable timeframe to avoid losing top talent"); strong_answer_signals=@("Knowledge of market compensation benchmarks","Emotional intelligence in handling objections","Ability to create win-win outcomes"); avoid=@("Being rigid on salary without flexibility","Making promises you cannot keep","Rushing the negotiation process")}},
    @{id="rta_014"; text="What is your approach to employer branding? How do you ensure the recruiting process reflects the companys values?"; category="motivation"; seniority=@("entry","mid","senior"); answer_framework=@{structure="Framework"; key_points=@("Understand the companys core values and mission before recruiting","Ensure every touchpoint from job ad to rejection email reflects brand values","Collect and showcase employee testimonials and stories","Monitor employer brand reputation on platforms like Glassdoor","Align recruiting messaging with the companys strategic positioning"); strong_answer_signals=@("Understanding that employer branding starts with every interaction","Using social media and content to attract talent","Connecting brand values to candidate experience"); avoid=@("Treating employer branding as just marketing material","Inconsistency between promised culture and actual hiring practices","Ignoring candidate feedback about brand perception")}},
    @{id="rta_015"; text="Explain how you would conduct executive search for a C-suite or senior leadership position. What makes it different from regular recruiting?"; category="technical"; seniority=@("senior","manager"); answer_framework=@{structure="Framework"; key_points=@("Engage in direct headhunting and networking rather than relying on job boards","Conduct thorough market mapping to identify both active and passive executives","Use confidentiality protocols to protect both client and candidate interests","Assess cultural fit and leadership philosophy alongside technical competencies","Manage a longer and more nuanced interview process with multiple stakeholders"); strong_answer_signals=@("Understanding of confidentiality and discretion requirements","Ability to assess leadership qualities beyond resume claims","Patience and strategic thinking in long-cycle searches"); avoid=@("Treating executive search like regular hiring","Rushing the assessment process","Ignoring cultural fit in favor of credentials alone")}},
    @{id="rta_016"; text="How do you manage volume hiring during peak recruitment seasons? What strategies do you use to maintain quality?"; category="situational"; seniority=@("mid","senior","manager"); answer_framework=@{structure="STAR"; key_points=@("Scaled sourcing efforts by leveraging multiple channels and agencies","Implemented structured interview processes with standardized scorecards","Used ATS automation to manage high volumes of applications","Prioritized roles and set clear SLAs with hiring managers","Maintained candidate experience through timely communication even at volume"); strong_answer_signals=@("Strategic prioritization under pressure","Use of technology and automation","Consistent candidate experience despite scale"); avoid=@("Sacrificing quality entirely for speed","Burning out the team with unsustainable workloads","Neglecting candidate communication due to volume")}},
    @{id="rta_017"; text="Tell me about your experience with graduate or campus recruiting. How do you build relationships with universities and early-career talent?"; category="technical"; seniority=@("entry","mid"); answer_framework=@{structure="Framework"; key_points=@("Develop partnerships with university career centers and faculty","Design internship and co-op programs to build a talent pipeline","Create compelling employer presentations and on-campus engagement events","Implement structured assessment programs for graduate candidates","Track early-career hire retention and conversion rates"); strong_answer_signals=@("Understanding of the graduate talent landscape","Long-term pipeline thinking","Ability to engage and inspire early-career professionals"); avoid=@("Treating campus recruiting as a one-time event","Not following up with candidates after campus visits","Ignoring feedback from university partners")}},
    @{id="rta_018"; text="Tell me about a time when you had to assess a candidates cultural fit. What specific behaviors or indicators did you look for?"; category="behavioral"; seniority=@("mid","senior"); answer_framework=@{structure="STAR"; key_points=@("Defined the teams core values and working style before the interview","Asked behavioral questions designed to reveal work style preferences","Observed how the candidate interacted with different team members","Compared the candidates values against the teams established norms","Provided honest feedback to the hiring manager on cultural alignment"); strong_answer_signals=@("Objective assessment of cultural fit","Avoiding bias in evaluation","Using structured methods rather than gut feelings"); avoid=@("Confusing cultural fit with finding people like yourself","Ignoring the value of diverse perspectives","Making snap judgments based on first impressions alone")}},
    @{id="rta_019"; text="How do you leverage LinkedIn Recruiter effectively? What features do you use most and how do they improve your sourcing?"; category="technical"; seniority=@("entry","mid","senior"); answer_framework=@{structure="Framework"; key_points=@("Use advanced search filters to narrow candidates by role, geography, and tenure","Leverage InMail for targeted outreach to passive candidates","Save and organize candidate searches with alerts for new matches","Use teamwork features to collaborate with hiring managers on candidate reviews","Analyze recruiter analytics to optimize your sourcing strategy"); strong_answer_signals=@("Demonstrated proficiency with Recruiter-specific features","Understanding of passive candidate outreach best practices","Data-driven approach to optimizing LinkedIn sourcing"); avoid=@("Sending generic InMail messages without personalization","Not using saved searches and alerts","Ignoring analytics and only relying on manual searches")}},
    @{id="rta_020"; text="A candidate accepts an offer but then reneges before starting. How do you handle this situation and what do you learn from it?"; category="situational"; seniority=@("mid","senior","manager"); answer_framework=@{structure="STAR"; key_points=@("Stayed professional and gracious while understanding the candidates reasons","Conducted a post-mortem to identify where the process could have been stronger","Revisited the offer package and onboarding experience for improvements","Maintained the candidate relationship for potential future opportunities","Implemented process changes such as more frequent check-ins between offer and start"); strong_answer_signals=@("Handling rejection with professionalism","Turning a negative experience into process improvement","Valuing long-term candidate relationships"); avoid=@("Taking it personally or becoming confrontational","Not investigating the root cause","Ignoring the impact on team morale and hiring timelines")}}
)
$json = @{metadata=@{sector="Recruiting / Talent Acquisition"; generated="2026-08-30"; total=20; schema_version="1.1"; categories=@("behavioral","technical","motivation","situational")}; questions=$questions}
$json | ConvertTo-Json -Depth 4 | Out-File -FilePath "D:\Claude\interview-aid-app\server\questions\recruiting_talent_acquisition_questions.json" -Encoding UTF8NoBOM -Force
Write-Host "Recruiting done!"
